    @Test
    public void testGetAttributeInfos_returnsMutableInternalList() {
        // 1. Arrange: Create a TypeInfo instance.
        //    Using String.class as an arbitrary class for the constructor.
        TypeInfo typeInfo = new TypeInfo(String.class);

        // 2. Act: Call the focal method to get the list of AttributeInfo objects.
        List<AttributeInfo> returnedList = typeInfo.getAttributeInfos();

        // 3. Assert: Verify the behavior and intention of the method.

        // A. Assert that the returned list is not null.
        assertNotNull("The getAttributeInfos() method should not return a null list.", returnedList);

        // B. Assert that the returned list is initially empty for a new TypeInfo instance.
        assertTrue("For a new TypeInfo instance, the attribute list should be empty.", returnedList.isEmpty());
        assertEquals("The initial size of the attribute list should be 0.", 0, returnedList.size());

        // C. Assert that the returned list is mutable and directly reflects the internal state.
        //    The method intention states "direct access to the internal, mutable list".
        //    Adding an item to 'returnedList' should modify the internal 'attrInfos'.
        AttributeInfo info1 = new AttributeInfo();
        returnedList.add(info1); // Modify the returned list

        assertEquals("After adding one item, the list size should be 1.", 1, returnedList.size());
        assertEquals("The added item should be present at index 0.", info1, returnedList.get(0));

        // D. Verify that subsequent calls return the *same* list instance, not a copy.
        List<AttributeInfo> returnedListAgain = typeInfo.getAttributeInfos();
        assertSame("Subsequent calls to getAttributeInfos() should return the same List instance.", returnedList, returnedListAgain);
        assertEquals("The list obtained from a second call should also contain the added item.", 1, returnedListAgain.size());

        // E. Verify that different TypeInfo instances have independent lists.
        TypeInfo anotherTypeInfo = new TypeInfo(Integer.class);
        List<AttributeInfo> anotherReturnedList = anotherTypeInfo.getAttributeInfos();

        assertNotNull("Another TypeInfo instance should also return a non-null list.", anotherReturnedList);
        assertTrue("Another TypeInfo's attribute list should be initially empty.", anotherReturnedList.isEmpty());
        assertNotSame("Different TypeInfo instances should have distinct List instances.", returnedList, anotherReturnedList);

        // Add an item to the second list and ensure it doesn't affect the first.
        anotherReturnedList.add(new AttributeInfo());
        assertEquals("Adding to 'anotherReturnedList' should make its size 1.", 1, anotherReturnedList.size());
        assertEquals("The original 'returnedList' should still have 1 item, unaffected by the second instance.", 1, returnedList.size());
    }
